def compute(vars):
    old_value = vars["v1"]
    new_value = vars["v2"]
    if old_value == 0:
        return None
    change = new_value - old_value
    growth_rate = change / old_value
    return {
        "value": growth_rate,
        "trace": {
            "old_value": old_value,
            "new_value": new_value,
            "change": change,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
